//
// Committed baseline for the stylesheet startup benchmark (issue #201): the checked-in
// `tests/golden/perf/stylesheet_benchmark.json` is decoded here, compared with the measured stage
// counters, and regenerated by `--update`. Structural counters (bytes, tokens, rules, selectors,
// declarations, keyframes, layers, container queries, diagnostics) are exact: they are a pure
// function of the stylesheet and the engine. Allocation counters carry a percentage tolerance
// because the standard library's container layout differs between toolchains, which shifts how
// many times a growable container allocates without changing what the path does.

#pragma once

#include "benchmark_paths.hpp"

#include <cstddef>

namespace tessera::benchmark {

struct Baseline {
    std::size_t css_bytes = 0;
    std::size_t css_tokens = 0;
    std::size_t blob_bytes = 0;
    std::size_t blob_load_allocations = 0;
    std::size_t blob_load_allocated_bytes = 0;
    std::size_t parse_prepare_allocations = 0;
    std::size_t parse_prepare_allocated_bytes = 0;
    std::size_t rules = 0;
    std::size_t selectors = 0;
    std::size_t declarations = 0;
    std::size_t diagnostics = 0;
    std::size_t keyframes = 0;
    std::size_t layers = 0;
    std::size_t container_queries = 0;
    double allocation_tolerance_percent = 0.0;
};

// Reads the committed baseline. False, with a message on stderr, when the file is missing, is not
// valid JSON, or omits a key the benchmark compares (a stale baseline must fail loudly).
[[nodiscard]] bool load_baseline(const char* path, Baseline& out);

// Writes `comparison` in the checked-in shape; `--update` uses it so the numbers are never edited
// by hand. Output is deterministic (fixed key order, LF, two-space indent).
[[nodiscard]] bool write_baseline(const char* path, const PathComparison& comparison);

} // namespace tessera::benchmark
